 		ArrayList<String> matchedList = new ArrayList<String>();
 		final PathMatcher pathMatcher = FileSystems.getDefault().getPathMatcher(glob);

-		Files.walkFileTree(Paths.get(location), new SimpleFileVisitor<Path>() {
